import SwiftUI
struct DashboardView:View{@ObservedObject var model:MenuBarManager;var body:some View{VStack(spacing:0){HStack{Image(systemName:"gauge.with.dots.needle.50percent").foregroundStyle(.blue);Text("SystemMonitor").font(.headline);Spacer();Circle().fill(.green).frame(width:7)}.padding();ScrollView{VStack(spacing:12){card("CPU","cpu"){row("总占用率",String(format:"%.1f%%",model.cpu.total));HStack(spacing:4){ForEach(Array(model.cpu.cores.enumerated()),id:\.offset){_,v in Capsule().fill(.blue.opacity(0.2)).overlay(alignment:.bottom){Capsule().fill(.blue).frame(height:max(2,36*v/100))}.frame(height:36)}};row("温度","不可用（无公开 API）");row("频率","不可用（无公开 API）")};card("内存","memorychip"){row("已使用",Fmt.size(model.memory.used));row("剩余",Fmt.size(model.memory.available));row("Cache",Fmt.size(model.memory.cached));row("Swap",Fmt.size(model.memory.swap));row("内存压力",model.memory.pressure)};card("磁盘","internaldrive"){row("已使用",Fmt.size(model.disk.used));row("剩余空间",Fmt.size(model.disk.available));row("读取速度",Fmt.speed(model.disk.read));row("写入速度",Fmt.speed(model.disk.write))};card("网络","network"){row("下载",Fmt.speed(model.network.download));row("上传",Fmt.speed(model.network.upload));row("当前 IP",model.network.ip)};if model.battery.present{card("电池","battery.75percent"){row("电量","\(model.battery.percent)%");row("状态",model.battery.charging ? "正在充电":"使用电池");row("剩余时间",model.battery.minutes.map{"\($0/60) 小时 \($0%60) 分"} ?? "正在计算")}}}.padding(12)};Divider();HStack{Button("设置…",action:model.settings);Spacer();Button("关于"){NSApp.orderFrontStandardAboutPanel(nil)};Button("退出"){NSApp.terminate(nil)}}.buttonStyle(.plain).padding()}.frame(width:340,height:640)}
 func row(_ a:String,_ b:String)->some View{HStack{Text(a).foregroundStyle(.secondary);Spacer();Text(b).monospacedDigit()}.font(.callout)}
 func card<C:View>(_ title:String,_ icon:String,@ViewBuilder content:()->C)->some View{VStack(spacing:8){HStack{Label(title,systemImage:icon).font(.headline);Spacer()};Divider();content()}.padding(12).background(.background.secondary,in:RoundedRectangle(cornerRadius:12))}}
